export default function prepare({ body }) {
  const { vendor, title, product_type } = body;
  return {
    tweet: `Hey there, my design is now on a new product ✨\nVisit my ${vendor} shop to get this cool${title} (and check out more ${product_type}) 🛍️`,
    telegram: `Hey there, my design is now on a new product!\nVisit my ${vendor} shop to get this cool${title} (and check out more ${product_type})`,
  };
}
